-- AISC Shapes Database v16.0H - Complete Historical Database
-- 18,878 shapes from 1873 to present
-- Includes W, S, HP, C, MC, L, 2L, WT, ST, MT, HSS, PIPE, and historical shapes
-- Generated from aisc-shapes-database-v16_0h.xlsx

DROP TABLE IF EXISTS aisc_shapes;

CREATE TABLE aisc_shapes (
    id INT AUTO_INCREMENT PRIMARY KEY,
    
    -- Identification
    edition VARCHAR(20) COMMENT 'AISC Manual edition',
    footnote VARCHAR(50) COMMENT 'Shape footnotes',
    type VARCHAR(20) COMMENT 'Shape type (W, S, C, L, HSS, etc.)',
    designation VARCHAR(50) COMMENT 'Shape designation',
    
    -- Basic dimensions
    a DECIMAL(12,4) COMMENT 'Cross-sectional area (in²)',
    d DECIMAL(12,4) COMMENT 'Depth (in)',
    tw DECIMAL(12,4) COMMENT 'Web thickness (in)',
    tw_2 DECIMAL(12,4) COMMENT 'Half web thickness (in)',
    bf DECIMAL(12,4) COMMENT 'Flange width (in)',
    tf DECIMAL(12,4) COMMENT 'Flange thickness (in)',
    t DECIMAL(12,4) COMMENT 'Thickness (in)',
    k DECIMAL(12,4) COMMENT 'Distance from outer face of flange to web toe of fillet (in)',
    k1 DECIMAL(12,4) COMMENT 'Distance from web centerline to flange toe of fillet (in)',
    w DECIMAL(12,4) COMMENT 'Weight per foot (lb/ft)',
    
    -- Slenderness ratios
    bf_2tf DECIMAL(12,4) COMMENT 'Flange slenderness ratio',
    h_tw DECIMAL(12,4) COMMENT 'Web slenderness ratio',
    
    -- Fy parameters
    fy_triple_prime VARCHAR(20) COMMENT 'Fy triple prime',
    x1 DECIMAL(12,4) COMMENT 'X1 parameter',
    x2x106 DECIMAL(12,4) COMMENT 'X2 x 10^6',
    
    -- Strong axis properties
    ix DECIMAL(14,4) COMMENT 'Moment of inertia about X-axis (in⁴)',
    zx DECIMAL(12,4) COMMENT 'Plastic section modulus about X-axis (in³)',
    sx DECIMAL(12,4) COMMENT 'Elastic section modulus about X-axis (in³)',
    rx DECIMAL(12,4) COMMENT 'Radius of gyration about X-axis (in)',
    
    -- Centroid
    y DECIMAL(12,4) COMMENT 'Y distance to centroid (in)',
    yp DECIMAL(12,4) COMMENT 'Y distance to plastic neutral axis (in)',
    
    -- Weak axis properties
    iy DECIMAL(14,4) COMMENT 'Moment of inertia about Y-axis (in⁴)',
    zy DECIMAL(12,4) COMMENT 'Plastic section modulus about Y-axis (in³)',
    sy DECIMAL(12,4) COMMENT 'Elastic section modulus about Y-axis (in³)',
    ry DECIMAL(12,4) COMMENT 'Radius of gyration about Y-axis (in)',
    
    -- Additional geometry
    x DECIMAL(12,4) COMMENT 'X distance to centroid (in)',
    xp DECIMAL(12,4) COMMENT 'X distance to plastic neutral axis (in)',
    rz DECIMAL(12,4) COMMENT 'Radius of gyration about Z-axis (in)',
    maxf DECIMAL(12,4) COMMENT 'Maximum flange dimension',
    grip DECIMAL(12,4) COMMENT 'Grip dimension',
    eo DECIMAL(12,4) COMMENT 'Shear center offset (in)',
    
    -- Q factors
    qs36 DECIMAL(12,4) COMMENT 'Qs for Fy=36 ksi',
    qs50 DECIMAL(12,4) COMMENT 'Qs for Fy=50 ksi',
    qs36c DECIMAL(12,4) COMMENT 'Qs compression for Fy=36 ksi',
    qs50c DECIMAL(12,4) COMMENT 'Qs compression for Fy=50 ksi',
    qs36s DECIMAL(12,4) COMMENT 'Qs stem for Fy=36 ksi',
    qs50s DECIMAL(12,4) COMMENT 'Qs stem for Fy=50 ksi',
    
    -- WT/ST stem properties
    astem DECIMAL(12,4) COMMENT 'Stem area (in²)',
    tanalpha DECIMAL(12,4) COMMENT 'tan(α) for angles',
    twstem DECIMAL(12,4) COMMENT 'Stem web thickness (in)',
    twstem_2 DECIMAL(12,4) COMMENT 'Half stem web thickness (in)',
    
    -- Pipe/HSS properties
    od DECIMAL(12,4) COMMENT 'Outside diameter (in)',
    shape_id DECIMAL(12,4) COMMENT 'Inside diameter (in)',
    twall DECIMAL(12,4) COMMENT 'Wall thickness (in)',
    j DECIMAL(14,4) COMMENT 'Torsional constant (in⁴)',
    t_1 DECIMAL(12,4) COMMENT 'Thickness alternate (in)',
    
    -- Alternate axis properties
    iy_prime DECIMAL(14,4) COMMENT 'Iy prime (in⁴)',
    sy_prime DECIMAL(12,4) COMMENT 'Sy prime (in³)',
    ry_prime DECIMAL(12,4) COMMENT 'ry prime (in)',
    sched VARCHAR(20) COMMENT 'Pipe schedule',
    
    -- A36 net section properties
    anet36 DECIMAL(12,4) COMMENT 'Net area A36 (in²)',
    d1a36 DECIMAL(12,4) COMMENT 'd1 A36 (in)',
    ixa36 DECIMAL(14,4) COMMENT 'Ix A36 (in⁴)',
    sxa36 DECIMAL(12,4) COMMENT 'Sx A36 (in³)',
    rxa36 DECIMAL(12,4) COMMENT 'rx A36 (in)',
    y1a36 DECIMAL(12,4) COMMENT 'y1 A36 (in)',
    rya36 DECIMAL(12,4) COMMENT 'ry A36 (in)',
    
    -- ASTM net section properties
    anetastm DECIMAL(12,4) COMMENT 'Net area ASTM (in²)',
    d1astm DECIMAL(12,4) COMMENT 'd1 ASTM (in)',
    ixastm DECIMAL(14,4) COMMENT 'Ix ASTM (in⁴)',
    sxastm DECIMAL(12,4) COMMENT 'Sx ASTM (in³)',
    rxastm DECIMAL(12,4) COMMENT 'rx ASTM (in)',
    y1astm DECIMAL(12,4) COMMENT 'y1 ASTM (in)',
    ryastm DECIMAL(12,4) COMMENT 'ry ASTM (in)',
    
    -- Angle ry values
    d_t DECIMAL(12,4) COMMENT 'd/t ratio',
    ry0 DECIMAL(12,4) COMMENT 'ry at 0 spacing',
    ry1_4 DECIMAL(12,4) COMMENT 'ry at 1/4 spacing',
    ry3_8 DECIMAL(12,4) COMMENT 'ry at 3/8 spacing',
    ry1_2 DECIMAL(12,4) COMMENT 'ry at 1/2 spacing',
    ry5_8 DECIMAL(12,4) COMMENT 'ry at 5/8 spacing',
    ry3_4 DECIMAL(12,4) COMMENT 'ry at 3/4 spacing',
    
    -- Additional parameters
    d_af DECIMAL(12,4) COMMENT 'd/Af ratio',
    rt DECIMAL(12,4) COMMENT 'rT (in)',
    fy_double_prime VARCHAR(20) COMMENT 'Fy double prime',
    cw DECIMAL(16,4) COMMENT 'Warping constant (in⁶)',
    fy_prime VARCHAR(20) COMMENT 'Fy prime',
    cc50_prime DECIMAL(12,4) COMMENT 'Cc for Fy=50 ksi',
    cc36_prime DECIMAL(12,4) COMMENT 'Cc for Fy=36 ksi',
    a_1 DECIMAL(12,4) COMMENT 'Dimension a (in)',
    wno DECIMAL(12,4) COMMENT 'Normalized warping function',
    sw DECIMAL(12,4) COMMENT 'Warping statical moment',
    sw1 DECIMAL(12,4) COMMENT 'Sw1 (in⁴)',
    sw2 DECIMAL(12,4) COMMENT 'Sw2 (in⁴)',
    sw3 DECIMAL(12,4) COMMENT 'Sw3 (in⁴)',
    qf DECIMAL(12,4) COMMENT 'Flange statical moment (in³)',
    qw DECIMAL(12,4) COMMENT 'Web statical moment (in³)',
    
    -- HSS specific
    b DECIMAL(12,4) COMMENT 'Width B (in)',
    b_1 DECIMAL(12,4) COMMENT 'Width b (in)',
    ht_t DECIMAL(12,4) COMMENT 'Ht/t ratio',
    h_tdes DECIMAL(12,4) COMMENT 'h/tdes ratio',
    b_tdes DECIMAL(12,4) COMMENT 'b/tdes ratio',
    d_t_1 DECIMAL(12,4) COMMENT 'D/t ratio',
    ht DECIMAL(12,4) COMMENT 'Height Ht (in)',
    h DECIMAL(12,4) COMMENT 'Flat height h (in)',
    tnom DECIMAL(12,4) COMMENT 'Nominal thickness (in)',
    tdes DECIMAL(12,4) COMMENT 'Design thickness (in)',
    b_t DECIMAL(12,4) COMMENT 'b/t ratio',
    c DECIMAL(12,4) COMMENT 'Torsional shear constant (in³)',
    ro DECIMAL(12,4) COMMENT 'Polar radius of gyration (in)',
    h_1 DECIMAL(12,4) COMMENT 'H parameter',
    
    -- Detailing dimensions
    ddet DECIMAL(12,4) COMMENT 'Detailing depth (in)',
    bfdet DECIMAL(12,4) COMMENT 'Detailing flange width (in)',
    twdet DECIMAL(12,4) COMMENT 'Detailing web thickness (in)',
    twdet_2 DECIMAL(12,4) COMMENT 'Half detailing web thickness (in)',
    tfdet DECIMAL(12,4) COMMENT 'Detailing flange thickness (in)',
    kdes DECIMAL(12,4) COMMENT 'Design k distance (in)',
    kdet DECIMAL(12,4) COMMENT 'Detailing k distance (in)',
    
    -- Additional ratios
    b_t_1 DECIMAL(12,4) COMMENT 'B/t ratio',
    sz DECIMAL(12,4) COMMENT 'Section modulus about Z-axis (in³)',
    qs DECIMAL(12,4) COMMENT 'Qs factor',
    iz DECIMAL(14,4) COMMENT 'Moment of inertia about Z-axis (in⁴)',
    iw DECIMAL(14,4) COMMENT 'Warping moment of inertia (in⁶)',
    
    -- Multi-point properties (z positions)
    za DECIMAL(12,4) COMMENT 'z at point A',
    zb DECIMAL(12,4) COMMENT 'z at point B',
    zc DECIMAL(12,4) COMMENT 'z at point C',
    wa DECIMAL(12,4) COMMENT 'w at point A',
    wb DECIMAL(12,4) COMMENT 'w at point B',
    wc DECIMAL(12,4) COMMENT 'w at point C',
    swa DECIMAL(12,4) COMMENT 'Sw at point A',
    swb DECIMAL(12,4) COMMENT 'Sw at point B',
    swc DECIMAL(12,4) COMMENT 'Sw at point C',
    sza DECIMAL(12,4) COMMENT 'Sz at point A',
    szb DECIMAL(12,4) COMMENT 'Sz at point B',
    szc DECIMAL(12,4) COMMENT 'Sz at point C',
    
    -- LTB parameters
    rts DECIMAL(12,4) COMMENT 'Effective radius of gyration for LTB (in)',
    ho DECIMAL(12,4) COMMENT 'Distance between flange centroids (in)',
    
    -- Gage dimensions
    pa DECIMAL(12,4) COMMENT 'Workable gage PA (in)',
    pb DECIMAL(12,4) COMMENT 'Workable gage PB (in)',
    pc DECIMAL(12,4) COMMENT 'Workable gage PC (in)',
    pd DECIMAL(12,4) COMMENT 'Workable gage PD (in)',
    wgi DECIMAL(12,4) COMMENT 'Workable gage inner (in)',
    wgo DECIMAL(12,4) COMMENT 'Workable gage outer (in)',
    
    -- Indexes
    INDEX idx_type (type),
    INDEX idx_designation (designation),
    INDEX idx_edition (edition),
    INDEX idx_weight (w),
    INDEX idx_depth (d),
    INDEX idx_area (a),
    INDEX idx_type_edition (type, edition)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='AISC v16.0H Complete Historical Shapes Database';
































































































































































































-- ============================================
-- USEFUL VIEWS FOR COMMON QUERIES
-- ============================================

-- Current edition W shapes
CREATE OR REPLACE VIEW v_current_w_shapes AS
SELECT designation, w, d, bf, tf, tw, a, ix, sx, zx, rx, iy, sy, zy, ry, j, cw
FROM aisc_shapes
WHERE type = 'W' AND edition = '15th'
ORDER BY w DESC;

-- Current edition HSS shapes  
CREATE OR REPLACE VIEW v_current_hss AS
SELECT designation, w, ht, b_1 as b, tdes, a, ix, sx, zx, rx, iy, sy, zy, ry, j, c
FROM aisc_shapes
WHERE type = 'HSS' AND edition = '15th'
ORDER BY w DESC;

-- Current edition channels
CREATE OR REPLACE VIEW v_current_channels AS
SELECT designation, w, d, bf, tf, tw, a, ix, sx, zx, rx, iy, sy, zy, ry, x, eo
FROM aisc_shapes
WHERE type IN ('C', 'MC') AND edition = '15th'
ORDER BY w DESC;

-- Current edition angles
CREATE OR REPLACE VIEW v_current_angles AS
SELECT designation, w, d, b_1 as b, t, a, ix, sx, rx, iy, sy, ry, rz, x, y
FROM aisc_shapes
WHERE type = 'L' AND edition = '15th'
ORDER BY w DESC;

-- Current edition pipes
CREATE OR REPLACE VIEW v_current_pipes AS
SELECT designation, w, od, twall, a, shape_id as id, ix, sx, rx, j, sched
FROM aisc_shapes
WHERE type = 'PIPE' AND edition = '15th'
ORDER BY w DESC;

-- Shape search by weight range
CREATE OR REPLACE VIEW v_shapes_by_weight AS
SELECT type, designation, edition, w, a, d, ix, iy
FROM aisc_shapes
ORDER BY type, w;

-- Historical shapes tracking
CREATE OR REPLACE VIEW v_shape_history AS
SELECT designation, type, edition, w, a, d, ix, sx
FROM aisc_shapes
ORDER BY designation, edition;
